// Лаба 2, п.2.8 — GET /api/info. Автор: Korol, группа ИИ-241
msg.payload = {
  student: "Korol",
  group: "ИИ-241"
};
return msg;

// Лаба 2, п.2.8 — GET /api/items. Автор: Korol, группа ИИ-241
const catalog = [
  { id: 1, name: "Ноутбук", price: 55000 },
  { id: 2, name: "Мышка", price: 1500 },
  { id: 3, name: "Клавиатура", price: 4500 }
];

const q = msg.req.query || {};          // query params: ?id=1
msg.topic = "lab2/Korol-ИИ-241/items";

if (q.id === undefined || q.id === "") {
  msg.statusCode = 400;                 // не передан обязательный параметр
  msg.payload = {
    error: "bad_request",
    message: "параметр ?id= обязателен",
    example: "/api/items?id=1",
    student: "Korol", group: "ИИ-241"
  };
  return msg;
}

const id = Number(q.id);
if (!Number.isInteger(id)) {
  msg.statusCode = 400;                 // id не число
  msg.payload = {
    error: "bad_request",
    message: "id должен быть целым числом, получено: " + q.id,
    student: "Korol", group: "ИИ-241"
  };
  return msg;
}

const item = catalog.find(function (it) { return it.id === id; });
if (!item) {
  msg.statusCode = 404;                 // не найдено
  msg.payload = {
    error: "not_found",
    message: "элемент с id=" + id + " не найден",
    student: "Korol", group: "ИИ-241"
  };
  return msg;
}

msg.statusCode = 200;
msg.payload = { success: true, item: item, student: "Korol", group: "ИИ-241" };
return msg;
